import{_ as i,o as l,c as e,am as n}from"./chunks/framework.CiF4W93w.js";const d=JSON.parse('{"title":"消息队列_RabbitMQ_基础概念","description":"","frontmatter":{"title":"消息队列_RabbitMQ_基础概念","excerpt":"消息队列_RabbitMQ_基础概念","date":"2023-12-28 20:54:23","updated":"2023-12-11 21:51:32"},"headers":[],"relativePath":"中间件/中间件 - 消息队列/MQ RabbitMQ/消息队列_RabbitMQ_基础概念.md","filePath":"中间件/中间件 - 消息队列/MQ RabbitMQ/消息队列_RabbitMQ_基础概念.md","lastUpdated":null}'),s={name:"中间件/中间件 - 消息队列/MQ RabbitMQ/消息队列_RabbitMQ_基础概念.md"};function t(o,a,p,r,c,u){return l(),e("div",null,[...a[0]||(a[0]=[n(`<blockquote><p>大纲</p></blockquote><ul><li>RabbitMQ是什么</li><li>RabbitMQ的组成部分</li><li>RabbitMQ 的工作流程</li><li>RabbitMQ广播和直接模式示例</li></ul><h3 id="一、基础概念" tabindex="-1">一、基础概念 <a class="header-anchor" href="#一、基础概念" aria-label="Permalink to &quot;一、基础概念&quot;">​</a></h3><p><strong>“消息队列(Message Queue)”是在消息的传输过程中保存消息的容器</strong>。</p><p>MQ 的核心作用：削峰、解耦、异步</p><h4 id="rabbitmq是什么" tabindex="-1">RabbitMQ是什么 <a class="header-anchor" href="#rabbitmq是什么" aria-label="Permalink to &quot;RabbitMQ是什么&quot;">​</a></h4><p>建议直接去官网看一下相关概念： <a href="https://www.rabbitmq.com/documentation.html" target="_blank" rel="noreferrer">https://www.rabbitmq.com/documentation.html</a></p><blockquote><p>RabbitMQ的特点</p></blockquote><p>RabbitMQ是一款使用Erlang语言开发的，实现AMQP(高级消息队列协议)的开源消息中间件。</p><p>特点</p><ul><li>可靠性。支持持久化，传输确认，发布确认等保证了MQ的可靠性。</li><li>灵活的分发消息策略。这应该是RabbitMQ的一大特点。在消息进入MQ前由Exchange(交换机)进行路由消息。分发消息策略有：简单模式、工作队列模式、发布订阅模式、路由模式、通配符模式。</li><li>支持集群。多台RabbitMQ服务器可以组成一个集群，形成一个逻辑Broker。</li><li>多种协议。RabbitMQ支持多种消息队列协议，比如 STOMP、MQTT 等等。</li><li>支持多种语言客户端。RabbitMQ几乎支持所有常用编程语言，包括 Java、.NET、Ruby 等等。</li><li>可视化管理界面。RabbitMQ提供了一个易用的用户界面，使得用户可以监控和管理消息 Broker。</li><li>插件机制。RabbitMQ提供了许多插件，可以通过插件进行扩展，也可以编写自己的插件。</li></ul><blockquote><p>安装和使用</p></blockquote><ul><li><ol><li>安装 erlang 环境</li></ol></li><li><ol start="2"><li>安装RabbitMQ服务端</li></ol></li></ul><h4 id="rabbitmq的组成部分" tabindex="-1">RabbitMQ的组成部分 <a class="header-anchor" href="#rabbitmq的组成部分" aria-label="Permalink to &quot;RabbitMQ的组成部分&quot;">​</a></h4><p>核心概念</p><ul><li>Broker：消息队列服务进程。此进程包括两个部分：Exchange和Queue。 <ul><li>Exchange：消息队列交换机。<strong>按一定的规则将消息路由转发到某个队列</strong>。</li><li>Queue：消息队列，存储消息的队列。</li></ul></li><li>Producer：消息生产者。生产方客户端将消息同交换机路由发送到队列中。</li><li>Consumer：消息消费者。消费队列中存储的消息。</li></ul><p>大概流程：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202312121056722.png" alt="image.png"></p><ul><li>消息生产者连接到RabbitMQ Broker，创建connection，开启channel。</li><li>生产者声明交换机类型、名称、是否持久化等。</li><li>生产者发送消息，并指定消息是否持久化等属性和 routing key。</li><li>exchange收到消息之后，<strong>根据routing key路由到跟当前交换机绑定的相匹配的队列</strong>里面。</li><li>消费者监听接收到消息之后开始业务处理</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生产者 --[消息]--&gt; 交换机 --[路由]--&gt; 队列 --[消费]--&gt; 消费者</span></span>
<span class="line"><span>    \\                                         /</span></span>
<span class="line"><span>     \\--[通道 Channel]-----------------------/</span></span></code></pre></div><p>通道的概念：</p><ul><li><strong>定义</strong>：通道是建立在实际的 TCP 连接内的一个轻量级连接。它是执行大多数操作（如消息发布或消息接收）的路径。</li><li><strong>作用</strong>：通道是多路复用连接中的一个独立路径，允许多个通道共享一个 TCP 连接，而不必为每个通道建立物理连接。这提高了资源利用率和通信效率</li><li>生产者使用通道来发送消息到交换机，而消费者使用通道从队列中接收消息。通道作为消息传输的通道，连接了生产者、交换机和消费者。</li></ul><p>通道是作为消息传递的载体贯穿整个过程。</p><h4 id="rabbitmq-的工作流程" tabindex="-1">RabbitMQ 的工作流程 <a class="header-anchor" href="#rabbitmq-的工作流程" aria-label="Permalink to &quot;RabbitMQ 的工作流程&quot;">​</a></h4><h5 id="工作流程" tabindex="-1">工作流程 <a class="header-anchor" href="#工作流程" aria-label="Permalink to &quot;工作流程&quot;">​</a></h5><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228022307.png" alt="image.png"></p><ul><li>建立连接</li><li>生产者 <ul><li>声明交换机类型、名称、是否持久化等</li><li>发送消息</li></ul></li><li>交换机 <ul><li>交换机接收消息，进行消息路由</li></ul></li><li>消费者 <ul><li>订阅消息（监听队列）</li><li>接收消息，业务处理</li></ul></li></ul><hr><p>一、消息生产</p><ul><li>创建连接 <ul><li>生产者通过客户端库与RabbitMQ服务器（Broker）建立连接（Connection），并在连接上创建一个信道（Channel）。</li></ul></li><li>创建消息（声明交换机，指定 routing key） <ul><li>生产者（Producer）是消息的发送方，它创建包含数据的消息，并指定一个<code>routing key</code>来描述这条消息的路由规则。</li></ul></li><li>发送消息 <ul><li>生产者将消息发送到一个指定的交换机（Exchange），并附上<code>routing key</code>。交换机类型和<code>routing key</code>共同决定了消息的路由方式。</li></ul></li></ul><p>二、消息路由</p><ul><li>交换机接收消息 <ul><li>交换机根据自身类型（如Direct, Fanout, Topic, Headers）和生产者指定的<code>routing key</code>来决定如何处理接收到的消息。</li></ul></li><li>路由队列 <ul><li>交换机根据与其绑定的队列（Queue）的<code>binding key</code>来决定消息应该被路由到哪些队列。</li><li>对于Direct和Topic交换机，这一过程涉及到<code>routing key</code>与<code>binding key</code>的匹配。</li></ul></li></ul><p>三、消息存储</p><ul><li>消息入队 <ul><li>一旦决定了消息的目标队列，消息将被存储在队列中等待被消费。队列保证了消息的有序性和冗余存储。</li></ul></li><li>持久化（可选） <ul><li>如果队列被声明为持久化的，并且消息也被标记为持久化，那么消息会被写入磁盘，以确保即使在RabbitMQ重启后消息也不会丢失。</li></ul></li></ul><p>四、消息消费</p><ul><li>消费者订阅队列 <ul><li>消费者（Consumer）通过客户端库与RabbitMQ建立连接，并创建信道。然后它订阅一个或多个队列，准备接收消息。</li></ul></li><li>消息发送给消费者 <ul><li>RabbitMQ将队列中的消息按顺序传递给订阅该队列的消费者。</li><li>如果有多个消费者订阅同一个队列，RabbitMQ可以按照轮询或其他策略分配消息，以实现负载均衡。</li></ul></li><li>消息确认 <ul><li>消费者处理完消息后，需要向RabbitMQ发送一个确认（ACK）信号，表示消息已经被正确处理。</li><li>如果消费者因为某些原因无法处理消息，它可以发送拒绝（NACK）信号或不确认（Reject），让RabbitMQ根据配置进行消息重试或将消息发送到死信队列。</li></ul></li></ul><p>五、消息确认与重试</p><ul><li>手动与自动确认 <ul><li>消费者可以选择手动确认消息或配置自动确认。手动确认给予消费者更大的控制权，但需要在消费者代码中显式处理。</li></ul></li><li>失败重试和死信处理 <ul><li>对于处理失败的消息，消费者可以通过NACK或Reject并设置重入队列标志来实现重试。或者通过死信交换机（DLX）机制将无法处理的消息转发到死信队列。</li></ul></li></ul><h5 id="交换机类型" tabindex="-1">交换机类型 <a class="header-anchor" href="#交换机类型" aria-label="Permalink to &quot;交换机类型&quot;">​</a></h5><p>（交换机 → 队列）</p><ul><li>Direct Exchange <ul><li><code>binding key</code> 与消息的 <code>routing key</code> 完全匹配队列</li></ul></li><li>Topic Exchange <ul><li>模式匹配</li></ul></li><li>Fanout Exchange <ul><li>广播（忽略 <code>routing key</code> ）</li></ul></li><li>Headers Exchange <ul><li>不依赖 <code>routing key</code>，头部属性匹配</li></ul></li></ul><hr><p>RabbitMQ 中最常用的几种交换机类型及其区别：</p><blockquote><ol><li>Direct Exchange（直接交换机）</li></ol></blockquote><ul><li><strong>行为</strong>：消息被路由到那些 <code>binding key</code> 与消息的 <code>routing key</code> 完全匹配的队列。</li><li><strong>用途</strong>：非常适合单播（unicast）或多播（multicast）路由场景，即一对一或一对多发送。</li></ul><blockquote><ol start="2"><li>Fanout Exchange（扇出交换机）</li></ol></blockquote><ul><li><strong>行为</strong>：消息被路由到所有与该交换机绑定的队列，忽略 <code>routing key</code>。</li><li><strong>用途</strong>：非常适合广播消息，如日志系统，其中消息需要被发送到多个目的地。</li></ul><blockquote><ol start="3"><li>Topic Exchange（主题交换机）</li></ol></blockquote><ul><li><strong>行为</strong>：可以根据模式匹配 <code>routing keys</code> 和 <code>binding keys</code>（模式中可以包含通配符）。<code>routing key</code> 为点分隔的一系列单词，<code>binding key</code> 中可以包含特殊字符 <code>*</code> 和 <code>#</code> 来进行模式匹配，其中 <code>*</code> 匹配一个单词，<code>#</code> 匹配零个或多个单词。</li><li><strong>用途</strong>：适用于同时需要单播和多播路由逻辑的复杂路由配置。</li></ul><blockquote><ol start="4"><li>Headers Exchange（头部交换机）</li></ol></blockquote><ul><li><strong>行为</strong>：基于消息头部（headers）中的属性进行匹配。不依赖 <code>routing key</code>。匹配规则可以是“所有”（<code>x-match=all</code>，即所有头部属性必须匹配）或“任何”（<code>x-match=any</code>，即任意头部属性匹配）。</li><li><strong>用途</strong>：适用于需要根据多个属性进行路由决策的高级路由策略。</li></ul><blockquote><p>总结</p></blockquote><p>选择哪种交换机类型主要取决于你的具体应用场景和消息路由需求。</p><p>直接交换机适合简单的单播路由，扇出交换机适合广播，主题交换机适合复杂的路由场景，而头部交换机适合基于多属性的路由决策。了解这些交换机的特点可以帮助你更好地设计消息路由策略，并充分利用 RabbitMQ 的强大功能。</p><p>RabbitMQ 的处理流程是围绕着连接、交换机、消息发送和消息接收这几个核心环节展开的。</p><h5 id="路由键-routing-key-的作用" tabindex="-1">路由键（Routing Key）的作用 <a class="header-anchor" href="#路由键-routing-key-的作用" aria-label="Permalink to &quot;路由键（Routing Key）的作用&quot;">​</a></h5><p>路由键是消息发布到 RabbitMQ 时<strong>附带的一个字符串标识</strong>，它的作用是帮助交换机决定如何路由消息。</p><p>这里的“路由”指的是决定消息应该被发送到哪一个或哪些队列。路由键的具体作用取决于交换机的类型：</p><ol><li><strong>Direct Exchange</strong>：交换机会将消息路由到那些 <code>binding key</code> 与 <code>routing key</code> 完全匹配的队列。</li><li><strong>Topic Exchange</strong>：可以进行模式匹配，交换机会根据 <code>routing key</code> 和队列的 <code>binding key</code>（可以包含通配符）进行匹配。</li><li><strong>Fanout Exchange</strong>：忽略路由键，消息会被发送到所有绑定到该交换机的队列。</li><li><strong>Headers Exchange</strong>：不依赖路由键，而是根据发送的消息头部中的键值对进行匹配。</li></ol><blockquote><p>routing key 和 binding key 的作用</p></blockquote><ul><li><code>routing key</code><ul><li>1、生产者发送消息的时候附加的一个字符串标识符</li><li>2、这个标识符的作用是：描述消息的路由规则，决定了这个消息应该路由到哪个队列</li></ul></li><li><code>binding key</code><ul><li>1、队列绑定交换机的时候声明的一个字符串标识符</li><li>2、这个标识符的作用取决于交换机的类型和预期的消息路由逻辑</li></ul></li></ul><p>单独抽离 <a href="./.html">消息队列_RabbitMQ_交换机类型#1、RabbitMQ广播和直接模式示例</a> 中关于 Direct Exchange 直接交换机的使用内容：</p><p>直接交换机是一种将消息路由到那些<code>binding key</code>与消息的<code>routing key</code>完全匹配的队列的交换机。</p><p>RabbitConfig 配置类内容</p><p>声明 Direct 交换机</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    /**</span></span>
<span class="line"><span>     * 声明Direct交换机 支持持久化.</span></span>
<span class="line"><span>     * 通过directExchange方法创建一个名为DIRECT_EXCHANGE的Direct交换机，并设置为支持持久化，这意味着交换机会在RabbitMQ重启后依然存在。</span></span>
<span class="line"><span>     *</span></span>
<span class="line"><span>     * @return the exchange</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    @Bean(&quot;directExchange&quot;)</span></span>
<span class="line"><span>    public Exchange directExchange() {</span></span>
<span class="line"><span>        return ExchangeBuilder.directExchange(&quot;DIRECT_EXCHANGE&quot;).durable(true).build();</span></span>
<span class="line"><span>    }</span></span></code></pre></div><p>声明一个队列</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    /**</span></span>
<span class="line"><span>     * 声明一个队列 支持持久化.</span></span>
<span class="line"><span>     *directQueue方法声明了一个名为DIRECT_QUEUE的队列，并设置为持久化。</span></span>
<span class="line"><span>     * @return the queue</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    @Bean(&quot;directQueue&quot;)</span></span>
<span class="line"><span>    public Queue directQueue() {</span></span>
<span class="line"><span>        return QueueBuilder.durable(&quot;DIRECT_QUEUE&quot;).build();</span></span>
<span class="line"><span>    }</span></span></code></pre></div><p>绑定队列到交换机</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    /**</span></span>
<span class="line"><span>     * 通过绑定键 将指定队列绑定到一个指定的交换机 .</span></span>
<span class="line"><span>     *directBinding方法通过BindingBuilder将DIRECT_QUEUE队列绑定到DIRECT_EXCHANGE交换机，绑定键为DIRECT_ROUTING_KEY。</span></span>
<span class="line"><span>     * 这意味着只有当消息的routing key为DIRECT_ROUTING_KEY时，消息才会被路由到DIRECT_QUEUE队列。</span></span>
<span class="line"><span>     * @param queue    the queue</span></span>
<span class="line"><span>     * @param exchange the exchange</span></span>
<span class="line"><span>     * @return the binding</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    @Bean</span></span>
<span class="line"><span>    public Binding directBinding(@Qualifier(&quot;directQueue&quot;) Queue queue,</span></span>
<span class="line"><span>                                 @Qualifier(&quot;directExchange&quot;) Exchange exchange) {</span></span>
<span class="line"><span>        return BindingBuilder.bind(queue).to(exchange).with(&quot;DIRECT_ROUTING_KEY&quot;).noargs();</span></span>
<span class="line"><span>    }</span></span></code></pre></div><p>发送测试</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    /**</span></span>
<span class="line"><span>     * 测试Direct模式.</span></span>
<span class="line"><span>     *</span></span>
<span class="line"><span>     * @param p the p</span></span>
<span class="line"><span>     * @return the response entity</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    public void direct(String p) {</span></span>
<span class="line"><span>        CorrelationData correlationData = new CorrelationData(UUID.randomUUID().toString());</span></span>
<span class="line"><span>        rabbitTemplate.convertAndSend(&quot;DIRECT_EXCHANGE&quot;, &quot;DIRECT_ROUTING_KEY&quot;, p, correlationData);</span></span>
<span class="line"><span>    }</span></span></code></pre></div><blockquote><p>交换机与消费者之间的协同</p></blockquote><p>交换机不直接与消费者通信来决定向哪个消费者发送消息。</p><p>相反，它依赖于队列和队列与消费者之间的关系来实现消息的分发。下面是它们是如何协同工作的：</p><ol><li><strong>队列绑定到交换机</strong>：队列通过 <code>binding key</code>（在 fanout 和 headers 交换机中，这个 <code>binding key</code> 不一定被使用）绑定到交换机。这个过程决定了哪些消息会被路由到特定的队列。</li><li><strong>消费者监听队列</strong>：消费者通过打开一个通道并订阅（或监听）一个或多个队列来接收消息。这意味着消费者告诉 RabbitMQ：“我对这个队列中的消息感兴趣，请将它们发送给我。”</li><li><strong>消息分发</strong>：当消息通过交换机被路由到队列后，RabbitMQ 会将队列中的消息发送给订阅该队列的消费者。这个分发过程可能是基于不同的策略，如轮询或公平调度等。</li></ol><h5 id="消费者的监听" tabindex="-1">消费者的监听 <a class="header-anchor" href="#消费者的监听" aria-label="Permalink to &quot;消费者的监听&quot;">​</a></h5><p>当我们说消费者“监听”一个队列时，实际上是指消费者开启了一个持续的、异步的过程，这个过程会等待、接收并处理来自队列的消息。</p><p>消费者通过通道向 RabbitMQ 注册其对特定队列的兴趣。一旦队列中有消息，RabbitMQ 就会将消息推送给消费者。消费者接收到消息后，会根据自己的逻辑进行处理。</p><p>消费者通过监听队列来接收消息，交换机本身并不决定消息发送给哪个消费者，这是由队列中的消息与消费者之间的关系决定的。<strong>消费者监听意味着它们准备好接收和处理从队列中来的消息。</strong></p><h3 id="二、常见面试题" tabindex="-1">二、常见面试题 <a class="header-anchor" href="#二、常见面试题" aria-label="Permalink to &quot;二、常见面试题&quot;">​</a></h3><p>常见生产问题以及如何处理和常见面试题</p><p><a href="/java/中间件/中间件 - 消息队列/MQ RabbitMQ/常见生产问题.html">消息队列_RabbitMQ_基础 - 常见面试题</a></p><ul><li>如何消息不丢失</li><li>如何避免消息重复消费</li><li>如何处理消息堆积问题</li><li>讲述一下 RabbitMQ 的死信队列</li><li>讲述一下 RabbitMQ 的延迟队列</li><li></li></ul><h3 id="三、高可用机制" tabindex="-1">三、高可用机制 <a class="header-anchor" href="#三、高可用机制" aria-label="Permalink to &quot;三、高可用机制&quot;">​</a></h3><p>在生产环境下，使用集群来保证高可用性</p><p>分为：普通集群、镜像集群、仲裁集群</p><h4 id="普通集群" tabindex="-1">普通集群 <a class="header-anchor" href="#普通集群" aria-label="Permalink to &quot;普通集群&quot;">​</a></h4><p>生产环境一般不使用普通集群</p><p>普通集群，或者叫标准集群（classic cluster ），具备下列特征：</p><ul><li>会在集群的各个节点间共享部分数据，包括：交换机、队列元信息。不包含队列中的消息。</li><li>当访问集群某节点时，如果队列不在该节点，会从数据所在节点传递到当前节点并返回</li><li>队列所在节点宕机，队列中的消息就会丢失</li></ul><h4 id="镜像集群" tabindex="-1">镜像集群 <a class="header-anchor" href="#镜像集群" aria-label="Permalink to &quot;镜像集群&quot;">​</a></h4><p>镜像集群：本质是主从模式，具备下面的特征：</p><ul><li>交换机、队列、队列中的消息会在各个 mq 的镜像节点之间同步备份。</li><li>创建队列的节点被称为该队列的主节点，备份到的其它节点叫做该队列的镜像节点。</li><li>一个队列的主节点可能是另一个队列的镜像节点</li><li>所有操作都是主节点完成，然后同步给镜像节点</li><li>主宕机后，镜像节点会替代成新的主节点</li></ul><h4 id="仲裁队列" tabindex="-1">仲裁队列 <a class="header-anchor" href="#仲裁队列" aria-label="Permalink to &quot;仲裁队列&quot;">​</a></h4><p>仲裁队列：仲裁队列是3.8版本以后才有的新功能，用来替代镜像队列，具备下列特征：</p><ul><li>与镜像队列一样，都是主从模式，支持主从数据同步</li><li>使用非常简单，没有复杂的配置</li><li>主从同步基于Raft协议，强一致 ·</li></ul><blockquote><p>面试题回答：RabbitMQ 的高可用机制有了解过吗</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228061905.png" alt="image.png"></p><p>参考回答；</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228061948.png" alt="image.png"></p><hr><p>参考</p><ul><li><a href="https://www.rabbitmq.com/documentation.html" target="_blank" rel="noreferrer">https://www.rabbitmq.com/documentation.html</a></li><li><a href="https://developer.aliyun.com/article/769883" target="_blank" rel="noreferrer">https://developer.aliyun.com/article/769883</a></li><li><a href="https://blog.csdn.net/CherryChenieth/article/details/124767155" target="_blank" rel="noreferrer">https://blog.csdn.net/CherryChenieth/article/details/124767155</a></li><li><a href="https://javaguide.cn/high-performance/message-queue/rabbitmq-questions.html" target="_blank" rel="noreferrer">https://javaguide.cn/high-performance/message-queue/rabbitmq-questions.html</a></li><li><a href="https://www.bilibili.com/video/BV1yT411H7YK" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1yT411H7YK</a></li></ul>`,104)])])}const h=i(s,[["render",t]]);export{d as __pageData,h as default};
